import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { publishSubjectHandler } from "../handlers/publishSubjectHandler";
import type { ApiError } from "../runtime/client";
import type { FactFoldSubjectEntityType } from "../types/FactFoldSubjectEntityType";
import type { PublishSubjectRequest } from "../types/PublishSubjectRequest";

type Data = Awaited<ReturnType<typeof publishSubjectHandler>>;
type Vars = { subjectId: FactFoldSubjectEntityType; req: PublishSubjectRequest };

export function usePublishSubject(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => publishSubjectHandler(vars.subjectId, vars.req),
    ...options,
  });
}
